# ── select accessions for this member ─────────────────────────────────────────
case "$MEMBER" in
  1) ACCESSIONS="$ACCESSIONS_1" ; COUNT=183 ;;
  2) ACCESSIONS="$ACCESSIONS_2" ; COUNT=183 ;;
  3) ACCESSIONS="$ACCESSIONS_3" ; COUNT=183 ;;
  4) ACCESSIONS="$ACCESSIONS_4" ; COUNT=183 ;;
  5) ACCESSIONS="$ACCESSIONS_5" ; COUNT=181 ;;
  *)
    echo "ERROR: --member must be 1-5."
    usage
    ;;
esac

# override with custom accessions if provided
if [[ -n "$CUSTOM_ACCESSIONS" ]]; then
  ACCESSIONS="$CUSTOM_ACCESSIONS"
  COUNT=$(echo "$CUSTOM_ACCESSIONS" | tr ',' '\n' | wc -l)
  echo "Member ${MEMBER}: using custom accession list (${COUNT} accessions)"
else
  echo "Member ${MEMBER}: using pre-assigned accession list (${COUNT} accessions)"
fi

if $DOWNLOAD; then
  echo "Mode: fetch manifest + samplesheet + download FASTQ files"
else
  echo "Mode: fetch manifest + samplesheet only  (re-run with --download to also pull FASTQ files)"
fi
echo ""

# ── run from the raw/ directory ────────────────────────────────────────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "${SCRIPT_DIR}/raw" || { echo "ERROR: could not cd into raw/"; exit 1; }

DOWNLOAD_FLAG=""
if $DOWNLOAD; then
  DOWNLOAD_FLAG="--download"
fi

encodefetch \
  --accessions "${ACCESSIONS}" \
  --assay-title "Histone ChIP-seq" \
  --target-label H3K27ac \
  --organism "Homo sapiens" \
  --file-type fastq \
  --status released \
  --threads 20 \
  --progress \
  --nfcore \
  ${DOWNLOAD_FLAG}
